import{describe,it,expect}from"vitest";import{ConversationContext}from"../../frontend/js-modules/voice/conversation-context.js";describe("ConversationContext",()=>{it("leaves text unchanged when there is no known entity yet",()=>{const e=new ConversationContext;expect(e.resolveReferences("plan a trip there")).toBe("plan a trip there")}),it('substitutes "there" with the last-mentioned entity',()=>{const e=new ConversationContext;e.remember({speaker:"user",text:"tell me about Kerala",entity:{name:"Kerala",type:"destination"}}),expect(e.resolveReferences("plan a trip there for 3 days")).toBe("plan a trip Kerala for 3 days")}),it('substitutes "it" and "that place" as well',()=>{const e=new ConversationContext;e.remember({speaker:"user",text:"x",entity:{name:"Goa"}}),expect(e.resolveReferences("bookmark it")).toBe("bookmark Goa"),expect(e.resolveReferences("save that place")).toBe("save Goa")}),it("keeps a bounded turn history",()=>{const e=new ConversationContext({maxTurns:3});for(let t=0;t<5;t++)e.remember({speaker:"user",text:`turn ${t}`});const t=e.getHistory();expect(t).toHaveLength(3),expect(t[0].text).toBe("turn 2")}),it("reset clears entity and history",()=>{const e=new ConversationContext;e.remember({speaker:"user",text:"x",entity:{name:"Goa"}}),e.reset(),expect(e.getLastEntity()).toBeNull(),expect(e.getHistory()).toEqual([])})});